<?php
 namespace QQWorld\Framework\App\Test\Unit\Response\HeaderProvider; use \QQWorld\Framework\App\Response\HeaderProvider\XFrameOptions; use \QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager as ObjectManagerHelper; class XFrameOptionsTest extends \PHPUnit\Framework\TestCase { const HEADER_NAME = 'X-Frame-Options'; const HEADER_VALUE = 'TEST_OPTION'; protected $object; protected function setUp() { $objectManager = new ObjectManagerHelper($this); $this->object = $objectManager->getObject( \QQWorld\Framework\App\Response\HeaderProvider\XFrameOptions::class, ['xFrameOpt' => $this::HEADER_VALUE] ); } public function testGetName() { $this->assertEquals($this::HEADER_NAME, $this->object->getName(), 'Wrong header name'); } public function testGetValue() { $this->assertEquals($this::HEADER_VALUE, $this->object->getValue(), 'Wrong header value'); } public function testCanApply() { $this->assertTrue($this->object->canApply(), 'Incorrect canApply result'); } } 